import{_ as t,o as r,c as a,a3 as i}from"./chunks/framework.DBpCFmh2.js";const p=JSON.parse('{"title":"文件系统 API","description":"目前代码中没有名为 `/api/fs/trash` 的路由；如需完整的回收站管理界面，可基于现有模块新增列出、清空、按时间筛选等端点。","frontmatter":{"title":"文件系统 API","description":"目前代码中没有名为 `/api/fs/trash` 的路由；如需完整的回收站管理界面，可基于现有模块新增列出、清空、按时间筛选等端点。"},"headers":[],"relativePath":"API-参考文档/Agent-HTTP-API/文件系统-API/index.md","filePath":"API-参考文档/Agent-HTTP-API/文件系统-API/index.md","lastUpdated":null}'),l={name:"API-参考文档/Agent-HTTP-API/文件系统-API/index.md"};function o(s,e,d,n,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="文件系统-api" tabindex="-1">文件系统 API <a class="header-anchor" href="#文件系统-api" aria-label="Permalink to &quot;文件系统 API&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js" target="_blank" rel="noreferrer">agent/src/security.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js" target="_blank" rel="noreferrer">agent/src/trash.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/workspace-manager.js" target="_blank" rel="noreferrer">src/side_panel/workspace-manager.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/integration/api.integration.test.js" target="_blank" rel="noreferrer">agent/test/integration/api.integration.test.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#简介">简介</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#端点参考">端点参考</a></li><li><a href="#依赖与安全分析">依赖与安全分析</a></li><li><a href="#性能与大小限制">性能与大小限制</a></li><li><a href="#客户端调用示例">客户端调用示例</a></li><li><a href="#故障排除指南">故障排除指南</a></li><li><a href="#结论">结论</a></li></ol><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p>本文件是 Agent 本地代理中文件系统相关 HTTP API 的完整参考文档。Agent 作为独立 Node.js 进程，通过本地 HTTP 接口为 Chrome 扩展侧提供文件读取、写入、上传、下载、目录列表、删除到回收站、从回收站恢复等能力。所有路径访问均经过白名单与硬阻止清单校验；二进制内容支持 base64 传输；大文件优先使用流式处理以避免内存膨胀。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>文件系统 API 主要实现于 Agent 服务端入口文件中，安全校验逻辑位于独立的安全模块，回收站逻辑位于独立的回收站模块；扩展侧 side panel 通过工作区管理器封装部分调用。</p><pre class="mermaid">graph TB
Client[&quot;浏览器/扩展前端&quot;] --&gt; Server[&quot;Agent 服务器&lt;br/&gt;agent/src/server.js&quot;]
Server --&gt; Security[&quot;路径安全检查&lt;br/&gt;agent/src/security.js&quot;]
Server --&gt; Trash[&quot;回收站模块&lt;br/&gt;agent/src/trash.js&quot;]
Client --&gt; WorkspaceManager[&quot;工作区管理器&lt;br/&gt;src/side_panel/workspace-manager.js&quot;]
WorkspaceManager --&gt; Server
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L752-L862" target="_blank" rel="noreferrer">agent/src/server.js#L752-L862</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L141-L250" target="_blank" rel="noreferrer">agent/src/trash.js#L141-L250</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/workspace-manager.js#L352-L370" target="_blank" rel="noreferrer">src/side_panel/workspace-manager.js#L352-L370</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L132-L136" target="_blank" rel="noreferrer">agent/src/server.js#L132-L136</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L752-L862" target="_blank" rel="noreferrer">agent/src/server.js#L752-L862</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L141-L250" target="_blank" rel="noreferrer">agent/src/trash.js#L141-L250</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/workspace-manager.js#L352-L370" target="_blank" rel="noreferrer">src/side_panel/workspace-manager.js#L352-L370</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li>Agent 服务器：统一路由分发、请求体解析、JSON 响应封装、日志记录、MIME 类型检测、ZIP 打包、流式读写。</li><li>路径安全检查：基于 <code>allowedPaths</code> 白名单、系统工作目录默认值、符号链接规范化、硬阻止敏感路径。</li><li>回收站模块：将删除目标移动到用户主目录下的回收站目录，支持跨设备移动、过期清理、恢复和条目列表。</li><li>扩展侧工作区管理器：封装写文件、下载文件、批量下载等常用调用。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L193-L213" target="_blank" rel="noreferrer">agent/src/server.js#L193-L213</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L752-L862" target="_blank" rel="noreferrer">agent/src/server.js#L752-L862</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L141-L250" target="_blank" rel="noreferrer">agent/src/trash.js#L141-L250</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/workspace-manager.js#L352-L370" target="_blank" rel="noreferrer">src/side_panel/workspace-manager.js#L352-L370</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>下图展示典型文件操作请求在扩展侧与 Agent 侧之间的交互流程。</p><pre class="mermaid">sequenceDiagram
participant Frontend as &quot;扩展前端&quot;
participant Manager as &quot;工作区管理器&quot;
participant Server as &quot;Agent 服务器&quot;
participant Security as &quot;路径安全检查&quot;
participant FS as &quot;文件系统&quot;
participant Trash as &quot;回收站模块&quot;
Frontend-&gt;&gt;Manager : &quot;调用 writeFileContent(path, content)&quot;
Manager-&gt;&gt;Server : &quot;POST /api/fs/write&quot;
Server-&gt;&gt;Security : &quot;checkPath(path)&quot;
Security--&gt;&gt;Server : &quot;{ allowed, resolved }&quot;
Server-&gt;&gt;FS : &quot;写入文件或二进制 Buffer&quot;
Server--&gt;&gt;Manager : &quot;{ success, size, path }&quot;
Manager--&gt;&gt;Frontend : &quot;返回结果&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/workspace-manager.js#L352-L357" target="_blank" rel="noreferrer">src/side_panel/workspace-manager.js#L352-L357</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1053-L1086" target="_blank" rel="noreferrer">agent/src/server.js#L1053-L1086</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><h2 id="端点参考" tabindex="-1">端点参考 <a class="header-anchor" href="#端点参考" aria-label="Permalink to &quot;端点参考&quot;">​</a></h2><h3 id="通用约定" tabindex="-1">通用约定 <a class="header-anchor" href="#通用约定" aria-label="Permalink to &quot;通用约定&quot;">​</a></h3><ul><li>基础地址：由扩展配置或状态接口返回的 Agent 本地服务地址。</li><li>认证：文件系统类接口通常要求已认证的 Agent 会话；未认证时可能直接拒绝。</li><li>响应格式：大多数 JSON 端点返回 <code>{ success, ... }</code> 结构；错误时 <code>success=false</code> 并包含 <code>error</code>。</li><li>路径参数：除非特别说明，路径均为字符串；服务端会进行规范化、绝对路径检查与白名单校验。</li><li>MIME 类型：服务端根据扩展名推断 MIME，用于下载响应头与预览场景。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L193-L213" target="_blank" rel="noreferrer">agent/src/server.js#L193-L213</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L722-L749" target="_blank" rel="noreferrer">agent/src/server.js#L722-L749</a></li></ul><hr><h3 id="api-fs-read-读取文件" tabindex="-1"><code>/api/fs/read</code>：读取文件 <a class="header-anchor" href="#api-fs-read-读取文件" aria-label="Permalink to &quot;\`/api/fs/read\`：读取文件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>HTTP 方法</td><td>POST</td></tr><tr><td>URL 模式</td><td><code>/api/fs/read</code></td></tr><tr><td>请求体</td><td><code>path</code>：要读取的文件路径</td></tr><tr><td>成功响应</td><td><code>{ success: true, content, size, path }</code></td></tr><tr><td>失败响应</td><td><code>{ success: false, error }</code></td></tr><tr><td>状态码</td><td>200 成功；400 路径是目录或内容过大；403 路径不在允许范围；404 文件不存在；500 内部错误</td></tr></tbody></table><p>处理要点：</p><ul><li>先执行路径安全检查。</li><li>判断是否为目录，若是则返回 400。</li><li>使用 <code>DEFAULT_MAX_SIZE</code> 或配置的 <code>fileMaxSize</code> 限制读取大小。</li><li>以 UTF-8 文本读取并返回 <code>content</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1036-L1050" target="_blank" rel="noreferrer">agent/src/server.js#L1036-L1050</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L132-L136" target="_blank" rel="noreferrer">agent/src/server.js#L132-L136</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/integration/api.integration.test.js#L257-L277" target="_blank" rel="noreferrer">agent/test/integration/api.integration.test.js#L257-L277</a></li></ul><hr><h3 id="api-fs-write-写入文件" tabindex="-1"><code>/api/fs/write</code>：写入文件 <a class="header-anchor" href="#api-fs-write-写入文件" aria-label="Permalink to &quot;\`/api/fs/write\`：写入文件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>HTTP 方法</td><td>POST</td></tr><tr><td>URL 模式</td><td><code>/api/fs/write</code></td></tr><tr><td>请求体</td><td><code>path</code>：目标路径；<code>content</code>：文本或 base64 编码内容；<code>encoding</code>：可选，<code>base64</code> 表示二进制</td></tr><tr><td>成功响应</td><td><code>{ success: true, size, path }</code></td></tr><tr><td>失败响应</td><td><code>{ success: false, error }</code></td></tr><tr><td>状态码</td><td>200 成功；400 内容过大或缺少必要字段；403 路径不允许；404 父目录创建失败；500 写入失败</td></tr></tbody></table><p>处理要点：</p><ul><li>路径安全检查后确保父目录存在。</li><li>若 <code>encoding=base64</code>，先将 base64 解码为 Buffer 再写入，避免损坏二进制文件。</li><li>对脚本扩展名或 shebang 内容自动移除执行权限。</li><li>写入大小受 <code>DEFAULT_MAX_SIZE</code> 或 <code>fileMaxSize</code> 限制。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1053-L1086" target="_blank" rel="noreferrer">agent/src/server.js#L1053-L1086</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L132-L136" target="_blank" rel="noreferrer">agent/src/server.js#L132-L136</a></li></ul><hr><h3 id="api-fs-upload-stream-流式上传" tabindex="-1"><code>/api/fs/upload-stream</code>：流式上传 <a class="header-anchor" href="#api-fs-upload-stream-流式上传" aria-label="Permalink to &quot;\`/api/fs/upload-stream\`：流式上传&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>HTTP 方法</td><td>POST</td></tr><tr><td>URL 模式</td><td><code>/api/fs/upload-stream?path=目标路径</code></td></tr><tr><td>请求体</td><td>原始二进制 body；路径通过查询参数 <code>path</code> 传递</td></tr><tr><td>成功响应</td><td><code>{ success: true, size, path }</code></td></tr><tr><td>失败响应</td><td><code>{ success: false, error }</code></td></tr><tr><td>状态码</td><td>200 成功；400 缺少路径、声明大小超限、接收大小超限或写入失败；403 路径不允许；500 内部错误</td></tr></tbody></table><p>处理要点：</p><ul><li>路径必须通过查询参数传入，避免 JSON 体中的路径被普通解析器误处理。</li><li>使用 <code>MAX_UPLOAD_SIZE</code> 限制流式上传大小。</li><li>同时校验 <code>Content-Length</code> 与实际接收字节数，防止伪造或异常连接。</li><li>自动创建目标父目录。</li><li>对脚本扩展名自动移除执行权限。</li><li>失败时尝试清理半成品文件。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L792-L862" target="_blank" rel="noreferrer">agent/src/server.js#L792-L862</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L132-L136" target="_blank" rel="noreferrer">agent/src/server.js#L132-L136</a></li></ul><hr><h3 id="api-files-upload-multipart-上传" tabindex="-1"><code>/api/files/upload</code>：multipart 上传 <a class="header-anchor" href="#api-files-upload-multipart-上传" aria-label="Permalink to &quot;\`/api/files/upload\`：multipart 上传&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>HTTP 方法</td><td>POST</td></tr><tr><td>URL 模式</td><td><code>/api/files/upload</code></td></tr><tr><td>请求体</td><td><code>multipart/form-data</code>，包含 <code>file</code> 字段</td></tr><tr><td>成功响应</td><td><code>{ success: true, path, name, size }</code></td></tr><tr><td>失败响应</td><td><code>{ success: false, error }</code></td></tr><tr><td>状态码</td><td>200 成功；400 上传失败；500 内部错误</td></tr></tbody></table><p>处理要点：</p><ul><li>文件名过滤危险字符并取 basename，防止路径穿越。</li><li>如果同名文件已存在，自动追加序号后缀。</li><li>写入工作目录，并记录 MIME 类型。</li><li>该接口会将整个文件读入内存，因此更适合中小文件；超大文件应使用流式上传。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L752-L790" target="_blank" rel="noreferrer">agent/src/server.js#L752-L790</a></li></ul><hr><h3 id="api-fs-download-下载文件" tabindex="-1"><code>/api/fs/download</code>：下载文件 <a class="header-anchor" href="#api-fs-download-下载文件" aria-label="Permalink to &quot;\`/api/fs/download\`：下载文件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>HTTP 方法</td><td>POST</td></tr><tr><td>URL 模式</td><td><code>/api/fs/download</code></td></tr><tr><td>请求体</td><td><code>path</code>：文件路径；或 <code>paths</code>：多个路径（见批量行为）</td></tr><tr><td>成功响应</td><td>单文件：<code>{ success: true, type: &#39;file&#39;, name, size, content, mimeType }</code><br>目录：<code>{ success: true, type: &#39;directory&#39;, name, size, content, mimeType: &#39;application/zip&#39; }</code></td></tr><tr><td>失败响应</td><td><code>{ success: false, error }</code></td></tr><tr><td>状态码</td><td>200 成功；400 缺少路径或文件过大；403 路径不允许；404 路径不存在；500 打包或读取失败</td></tr></tbody></table><p>处理要点：</p><ul><li>单文件返回 base64 编码内容和 MIME 类型。</li><li>目录自动打包为 ZIP，返回 ZIP 的 base64 内容。</li><li>文件大小受 <code>DEFAULT_MAX_SIZE</code> 或 <code>fileMaxSize</code> 限制。</li><li>对于大文件，建议使用 <code>/api/fs/download-stream</code> 或 <code>/api/fs/download-multi</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1163-L1220" target="_blank" rel="noreferrer">agent/src/server.js#L1163-L1220</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L193-L213" target="_blank" rel="noreferrer">agent/src/server.js#L193-L213</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L132-L136" target="_blank" rel="noreferrer">agent/src/server.js#L132-L136</a></li></ul><hr><h3 id="api-fs-list-目录列表" tabindex="-1"><code>/api/fs/list</code>：目录列表 <a class="header-anchor" href="#api-fs-list-目录列表" aria-label="Permalink to &quot;\`/api/fs/list\`：目录列表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>HTTP 方法</td><td>POST</td></tr><tr><td>URL 模式</td><td><code>/api/fs/list</code></td></tr><tr><td>请求体</td><td><code>path</code>：目录路径；默认为当前工作目录</td></tr><tr><td>成功响应</td><td><code>{ success: true, entries, path }</code></td></tr><tr><td>失败响应</td><td><code>{ success: false, error }</code></td></tr><tr><td>状态码</td><td>200 成功；400 路径不是目录；403 路径不允许；404 目录不存在</td></tr></tbody></table><p><code>entries</code> 元素结构：</p><ul><li><code>name</code>：名称</li><li><code>type</code>：<code>file</code>、<code>directory</code> 或 <code>unknown</code></li><li><code>size</code>：字节数</li><li><code>mtime</code>：修改时间毫秒时间戳</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1090-L1110" target="_blank" rel="noreferrer">agent/src/server.js#L1090-L1110</a></li></ul><hr><h3 id="api-fs-delete-删除到回收站" tabindex="-1"><code>/api/fs/delete</code>：删除到回收站 <a class="header-anchor" href="#api-fs-delete-删除到回收站" aria-label="Permalink to &quot;\`/api/fs/delete\`：删除到回收站&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>HTTP 方法</td><td>POST</td></tr><tr><td>URL 模式</td><td><code>/api/fs/delete</code></td></tr><tr><td>请求体</td><td><code>path</code>：要删除的文件或目录路径</td></tr><tr><td>成功响应</td><td><code>{ success: true, path, isDir, trashId, message }</code></td></tr><tr><td>失败响应</td><td><code>{ success: false, error }</code></td></tr><tr><td>状态码</td><td>200 成功；403 路径不允许；404 路径不存在；500 移动到回收站失败</td></tr></tbody></table><p>处理要点：</p><ul><li>删除不会立即物理删除，而是移动到回收站。</li><li>返回 <code>trashId</code>，可用于后续恢复。</li><li>回收站支持过期自动清理。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1144-L1161" target="_blank" rel="noreferrer">agent/src/server.js#L1144-L1161</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L141-L202" target="_blank" rel="noreferrer">agent/src/trash.js#L141-L202</a></li></ul><hr><h3 id="api-trash-restore-从回收站恢复" tabindex="-1"><code>/api/trash/restore</code>：从回收站恢复 <a class="header-anchor" href="#api-trash-restore-从回收站恢复" aria-label="Permalink to &quot;\`/api/trash/restore\`：从回收站恢复&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>HTTP 方法</td><td>POST</td></tr><tr><td>URL 模式</td><td><code>/api/trash/restore</code></td></tr><tr><td>请求体</td><td><code>trashId</code>：回收站条目 ID</td></tr><tr><td>成功响应</td><td><code>{ success: true, restoredPath }</code></td></tr><tr><td>失败响应</td><td><code>{ success: false, error }</code></td></tr><tr><td>状态码</td><td>200 成功；400 缺少 trashId、原路径被占用、恢复失败；500 内部错误</td></tr></tbody></table><p>处理要点：</p><ul><li>若原路径已被占用，恢复失败。</li><li>恢复成功后从回收站元数据中移除对应条目。</li><li>支持跨设备移动，失败时清理半成品目标。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1693-L1703" target="_blank" rel="noreferrer">agent/src/server.js#L1693-L1703</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L210-L240" target="_blank" rel="noreferrer">agent/src/trash.js#L210-L240</a></li></ul><hr><h3 id="回收站管理端点说明" tabindex="-1">回收站管理端点说明 <a class="header-anchor" href="#回收站管理端点说明" aria-label="Permalink to &quot;回收站管理端点说明&quot;">​</a></h3><p>仓库中明确实现的回收站相关端点是：</p><ul><li><code>/api/fs/delete</code>：将文件/目录移动到回收站。</li><li><code>/api/trash/restore</code>：根据 <code>trashId</code> 恢复文件/目录。</li></ul><p>回收站模块还提供：</p><ul><li>回收站条目列表：<code>listTrash()</code></li><li>回收站目录路径：<code>getTrashDir()</code></li><li>定期清理过期条目：<code>startPeriodicCleanup()</code></li></ul><p>目前代码中没有名为 <code>/api/fs/trash</code> 的路由；如需完整的回收站管理界面，可基于现有模块新增列出、清空、按时间筛选等端点。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1144-L1161" target="_blank" rel="noreferrer">agent/src/server.js#L1144-L1161</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1693-L1703" target="_blank" rel="noreferrer">agent/src/server.js#L1693-L1703</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/trash.js#L242-L274" target="_blank" rel="noreferrer">agent/src/trash.js#L242-L274</a></li></ul><hr><h3 id="其他相关文件系统端点" tabindex="-1">其他相关文件系统端点 <a class="header-anchor" href="#其他相关文件系统端点" aria-label="Permalink to &quot;其他相关文件系统端点&quot;">​</a></h3><p>虽然不在问题描述的核心列表中，但以下端点与文件系统 API 密切相关，建议一并了解：</p><table tabindex="0"><thead><tr><th>端点</th><th>用途</th><th>关键行为</th></tr></thead><tbody><tr><td><code>/api/fs/stat</code></td><td>获取文件详细信息</td><td>返回类型、大小、时间戳、权限、MIME 类型等</td></tr><tr><td><code>/api/fs/mkdir</code></td><td>创建目录</td><td>递归创建失败时返回冲突或错误</td></tr><tr><td><code>/api/fs/rename</code></td><td>重命名文件/目录</td><td>仅改文件名，不跨目录；目标路径也需通过安全检查</td></tr><tr><td><code>/api/fs/move</code></td><td>移动文件/目录</td><td>目标路径同样需要安全检查</td></tr><tr><td><code>/api/fs/download-multi</code></td><td>批量下载</td><td>后端打包为 ZIP，返回 base64</td></tr><tr><td><code>/api/fs/download-stream</code></td><td>流式下载</td><td>单文件或目录打包后流式返回，避免 base64 膨胀</td></tr><tr><td><code>/api/fs/search_files</code></td><td>按文件名搜索</td><td>支持模式匹配和递归</td></tr><tr><td><code>/api/fs/search_content</code></td><td>按内容搜索</td><td>支持正则、大小写、上下文行数</td></tr><tr><td><code>/api/fs/preview-xlsx</code></td><td>Excel 预览</td><td>服务端解析前若干行，返回结构化 JSON</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1112-L1142" target="_blank" rel="noreferrer">agent/src/server.js#L1112-L1142</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1222-L1385" target="_blank" rel="noreferrer">agent/src/server.js#L1222-L1385</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1387-L1442" target="_blank" rel="noreferrer">agent/src/server.js#L1387-L1442</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1444-L1515" target="_blank" rel="noreferrer">agent/src/server.js#L1444-L1515</a></li></ul><h2 id="依赖与安全分析" tabindex="-1">依赖与安全分析 <a class="header-anchor" href="#依赖与安全分析" aria-label="Permalink to &quot;依赖与安全分析&quot;">​</a></h2><h3 id="路径安全检查" tabindex="-1">路径安全检查 <a class="header-anchor" href="#路径安全检查" aria-label="Permalink to &quot;路径安全检查&quot;">​</a></h3><p>所有涉及用户路径的文件系统操作都会调用路径安全检查函数。其核心规则包括：</p><ul><li>空路径或非字符串路径直接拒绝。</li><li>解析为绝对路径并进行规范化。</li><li>检查是否命中硬阻止敏感路径。</li><li>检查是否在 <code>allowedPaths</code> 白名单内。</li><li>使用真实路径再次校验，防止符号链接绕过。</li><li>Windows 下路径比较大小写不敏感。</li></ul><pre class="mermaid">flowchart TD
Start[&quot;收到路径&quot;] --&gt; Validate[&quot;验证路径类型&quot;]
Validate --&gt; Valid{&quot;路径有效？&quot;}
Valid --&gt; |否| DenyInvalid[&quot;拒绝：路径无效&quot;]
Valid --&gt; |是| Normalize[&quot;规范化并解析绝对路径&quot;]
Normalize --&gt; HardBlocked{&quot;命中硬阻止清单？&quot;}
HardBlocked --&gt; |是| DenyHard[&quot;拒绝：敏感路径&quot;]
HardBlocked --&gt; |否| AllowedCheck[&quot;检查 allowedPaths 白名单&quot;]
AllowedCheck --&gt; Allowed{&quot;在白名单内？&quot;}
Allowed --&gt; |否| DenyRange[&quot;拒绝：路径不在允许范围&quot;]
Allowed --&gt; |是| RealPath[&quot;解析真实路径&quot;]
RealPath --&gt; FinalCheck[&quot;再次前缀校验&quot;]
FinalCheck --&gt; Allow[&quot;允许：返回 resolved 路径&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L77-L100" target="_blank" rel="noreferrer">agent/src/security.js#L77-L100</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><h3 id="mime-类型检测" tabindex="-1">MIME 类型检测 <a class="header-anchor" href="#mime-类型检测" aria-label="Permalink to &quot;MIME 类型检测&quot;">​</a></h3><p>服务端根据文件扩展名映射 MIME 类型，用于下载响应头和预览场景。未知扩展名通常回退到通用类型。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L193-L213" target="_blank" rel="noreferrer">agent/src/server.js#L193-L213</a></li></ul><h3 id="批量操作支持" tabindex="-1">批量操作支持 <a class="header-anchor" href="#批量操作支持" aria-label="Permalink to &quot;批量操作支持&quot;">​</a></h3><ul><li><code>/api/fs/download-multi</code>：接受 <code>paths</code> 数组，在后端打包为 ZIP。</li><li><code>/api/fs/download-stream</code>：同时支持 <code>path</code> 和 <code>paths</code>，多文件时打包为 ZIP 流式返回。</li><li>扩展侧提供 <code>downloadFiles(paths)</code> 调用封装。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1222-L1385" target="_blank" rel="noreferrer">agent/src/server.js#L1222-L1385</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/workspace-manager.js#L366-L371" target="_blank" rel="noreferrer">src/side_panel/workspace-manager.js#L366-L371</a></li></ul><h2 id="性能与大小限制" tabindex="-1">性能与大小限制 <a class="header-anchor" href="#性能与大小限制" aria-label="Permalink to &quot;性能与大小限制&quot;">​</a></h2><h3 id="大小限制常量" tabindex="-1">大小限制常量 <a class="header-anchor" href="#大小限制常量" aria-label="Permalink to &quot;大小限制常量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>常量</th><th>值</th><th>适用场景</th></tr></thead><tbody><tr><td><code>DEFAULT_MAX_SIZE</code></td><td>50MB</td><td>读取文件、stat、download 等读取类操作的默认上限</td></tr><tr><td><code>MAX_UPLOAD_SIZE</code></td><td>200MB</td><td>流式上传 <code>/api/fs/upload-stream</code> 的上限</td></tr><tr><td><code>MAX_BODY_SIZE</code></td><td>200MB</td><td>JSON body 解析上限，影响旧版 base64 上传</td></tr><tr><td><code>config.fileMaxSize</code></td><td>可配置</td><td>覆盖 <code>DEFAULT_MAX_SIZE</code>，用于 read/download 等读取限制</td></tr></tbody></table><p>注意：</p><ul><li><code>/api/fs/read</code> 和 <code>/api/fs/download</code> 使用 <code>config.fileMaxSize || DEFAULT_MAX_SIZE</code>。</li><li><code>/api/fs/upload-stream</code> 使用 <code>MAX_UPLOAD_SIZE</code>，因为流式写入不会把整个文件加载到内存。</li><li><code>/api/files/upload</code> 会把 multipart 文件整体读入内存，适合中小文件。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L132-L136" target="_blank" rel="noreferrer">agent/src/server.js#L132-L136</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L722-L749" target="_blank" rel="noreferrer">agent/src/server.js#L722-L749</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L752-L790" target="_blank" rel="noreferrer">agent/src/server.js#L752-L790</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L792-L862" target="_blank" rel="noreferrer">agent/src/server.js#L792-L862</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1036-L1050" target="_blank" rel="noreferrer">agent/src/server.js#L1036-L1050</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1163-L1220" target="_blank" rel="noreferrer">agent/src/server.js#L1163-L1220</a></li></ul><h3 id="流式处理优化" tabindex="-1">流式处理优化 <a class="header-anchor" href="#流式处理优化" aria-label="Permalink to &quot;流式处理优化&quot;">​</a></h3><ul><li>流式上传：边接收边写入磁盘，实时统计字节数并在超过上限时中断。</li><li>流式下载：单文件使用 <code>createReadStream</code> 直接管道输出；目录打包后分块写入响应，避免一次性发送大 Buffer。</li><li>批量下载：后端打包 ZIP，前端可选择 base64 下载或流式下载。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L813-L856" target="_blank" rel="noreferrer">agent/src/server.js#L813-L856</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1267-L1385" target="_blank" rel="noreferrer">agent/src/server.js#L1267-L1385</a></li></ul><h2 id="客户端调用示例" tabindex="-1">客户端调用示例 <a class="header-anchor" href="#客户端调用示例" aria-label="Permalink to &quot;客户端调用示例&quot;">​</a></h2><h3 id="javascript-调用方式说明" tabindex="-1">JavaScript 调用方式说明 <a class="header-anchor" href="#javascript-调用方式说明" aria-label="Permalink to &quot;JavaScript 调用方式说明&quot;">​</a></h3><p>由于文档规范禁止直接粘贴具体代码片段，下面给出调用步骤和数据结构说明，便于自行实现。</p><h4 id="读取文件" tabindex="-1">读取文件 <a class="header-anchor" href="#读取文件" aria-label="Permalink to &quot;读取文件&quot;">​</a></h4><ul><li>向 <code>/api/fs/read</code> 发送 POST 请求。</li><li>请求体包含 <code>path</code>。</li><li>成功响应包含 <code>content</code>、<code>size</code>、<code>path</code>。</li><li>错误时检查 <code>success=false</code> 和 <code>error</code> 字段。</li></ul><h4 id="写入文件" tabindex="-1">写入文件 <a class="header-anchor" href="#写入文件" aria-label="Permalink to &quot;写入文件&quot;">​</a></h4><ul><li>向 <code>/api/fs/write</code> 发送 POST 请求。</li><li>文本写入：<code>{ path, content }</code>。</li><li>二进制写入：<code>{ path, content, encoding: &#39;base64&#39; }</code>。</li><li>成功响应包含 <code>size</code>、<code>path</code>。</li></ul><h4 id="流式上传" tabindex="-1">流式上传 <a class="header-anchor" href="#流式上传" aria-label="Permalink to &quot;流式上传&quot;">​</a></h4><ul><li>向 <code>/api/fs/upload-stream?path=目标路径</code> 发送 POST 请求。</li><li>请求体为原始二进制数据。</li><li>成功响应包含 <code>size</code>、<code>path</code>。</li></ul><h4 id="multipart-上传" tabindex="-1">multipart 上传 <a class="header-anchor" href="#multipart-上传" aria-label="Permalink to &quot;multipart 上传&quot;">​</a></h4><ul><li>向 <code>/api/files/upload</code> 发送 POST 请求。</li><li>使用 <code>multipart/form-data</code>，字段名为 <code>file</code>。</li><li>成功响应包含 <code>path</code>、<code>name</code>、<code>size</code>。</li></ul><h4 id="下载文件" tabindex="-1">下载文件 <a class="header-anchor" href="#下载文件" aria-label="Permalink to &quot;下载文件&quot;">​</a></h4><ul><li>小文件：使用 <code>/api/fs/download</code>，处理返回的 base64 <code>content</code>。</li><li>大文件：使用 <code>/api/fs/download-stream</code>，直接处理二进制流。</li><li>目录：两者都支持，目录会被打包为 ZIP。</li></ul><h4 id="目录列表" tabindex="-1">目录列表 <a class="header-anchor" href="#目录列表" aria-label="Permalink to &quot;目录列表&quot;">​</a></h4><ul><li>向 <code>/api/fs/list</code> 发送 POST 请求。</li><li>请求体包含 <code>path</code>。</li><li>成功响应包含 <code>entries</code> 数组。</li></ul><h4 id="删除到回收站" tabindex="-1">删除到回收站 <a class="header-anchor" href="#删除到回收站" aria-label="Permalink to &quot;删除到回收站&quot;">​</a></h4><ul><li>向 <code>/api/fs/delete</code> 发送 POST 请求。</li><li>请求体包含 <code>path</code>。</li><li>成功响应包含 <code>trashId</code>。</li></ul><h4 id="从回收站恢复" tabindex="-1">从回收站恢复 <a class="header-anchor" href="#从回收站恢复" aria-label="Permalink to &quot;从回收站恢复&quot;">​</a></h4><ul><li>向 <code>/api/trash/restore</code> 发送 POST 请求。</li><li>请求体包含 <code>trashId</code>。</li><li>成功响应包含 <code>restoredPath</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1036-L1050" target="_blank" rel="noreferrer">agent/src/server.js#L1036-L1050</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1053-L1086" target="_blank" rel="noreferrer">agent/src/server.js#L1053-L1086</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L792-L862" target="_blank" rel="noreferrer">agent/src/server.js#L792-L862</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L752-L790" target="_blank" rel="noreferrer">agent/src/server.js#L752-L790</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1163-L1385" target="_blank" rel="noreferrer">agent/src/server.js#L1163-L1385</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1144-L1161" target="_blank" rel="noreferrer">agent/src/server.js#L1144-L1161</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1693-L1703" target="_blank" rel="noreferrer">agent/src/server.js#L1693-L1703</a></li></ul><h2 id="故障排除指南" tabindex="-1">故障排除指南 <a class="header-anchor" href="#故障排除指南" aria-label="Permalink to &quot;故障排除指南&quot;">​</a></h2><h3 id="常见错误与原因" tabindex="-1">常见错误与原因 <a class="header-anchor" href="#常见错误与原因" aria-label="Permalink to &quot;常见错误与原因&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>处理建议</th></tr></thead><tbody><tr><td>读取文件返回 403</td><td>路径不在 <code>allowedPaths</code> 白名单或命中硬阻止清单</td><td>检查工作目录和允许路径配置</td></tr><tr><td>读取文件返回 404</td><td>文件不存在</td><td>确认路径是否正确</td></tr><tr><td>读取文件返回 400</td><td>目标是目录或文件大小超过限制</td><td>使用 list 查看目录；增大 <code>fileMaxSize</code> 或使用下载流</td></tr><tr><td>写入文件返回 403</td><td>目标路径不在允许范围</td><td>调整工作目录或允许路径</td></tr><tr><td>写入文件返回 400</td><td>内容超过限制或编码异常</td><td>检查 <code>encoding=base64</code> 的使用；减小内容体积</td></tr><tr><td>流式上传返回 400</td><td>缺少 <code>path</code>、声明大小超限、实际接收大小超限</td><td>检查查询参数和请求体大小</td></tr><tr><td>下载返回 400</td><td>文件过大或参数缺失</td><td>改用 <code>/api/fs/download-stream</code></td></tr><tr><td>删除返回 500</td><td>移动到回收站失败</td><td>检查回收站目录权限和磁盘空间</td></tr><tr><td>恢复返回 400</td><td>原路径被占用或回收站条目不存在</td><td>检查原路径是否被新文件占用</td></tr></tbody></table><h3 id="调试建议" tabindex="-1">调试建议 <a class="header-anchor" href="#调试建议" aria-label="Permalink to &quot;调试建议&quot;">​</a></h3><ul><li>先调用状态接口确认 Agent 版本、工作目录、允许路径、文件大小限制。</li><li>使用 <code>/api/fs/stat</code> 检查目标路径的类型、大小、权限和时间戳。</li><li>使用 <code>/api/fs/list</code> 确认目录内容。</li><li>查看 Agent 日志中的 <code>fs_*</code> 和 <code>security_*</code> 分类日志。</li><li>对于路径安全问题，优先检查 <code>allowedPaths</code> 和工作目录配置。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L722-L749" target="_blank" rel="noreferrer">agent/src/server.js#L722-L749</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1112-L1142" target="_blank" rel="noreferrer">agent/src/server.js#L1112-L1142</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1144-L1161" target="_blank" rel="noreferrer">agent/src/server.js#L1144-L1161</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1693-L1703" target="_blank" rel="noreferrer">agent/src/server.js#L1693-L1703</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/integration/api.integration.test.js#L257-L277" target="_blank" rel="noreferrer">agent/test/integration/api.integration.test.js#L257-L277</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>文件系统 API 围绕 Agent 本地服务构建，提供安全的文件读写、上传、下载、目录管理和回收站能力。核心安全机制是路径白名单与硬阻止清单；核心性能机制是流式上传与流式下载；核心用户体验机制是回收站和批量操作。客户端应根据文件大小选择合适的接口：小文件可用 base64 下载，大文件应使用流式下载；上传大文件时应使用流式上传而非 multipart。</p>`,156)])])}const b=t(l,[["render",o]]);export{p as __pageData,b as default};
